module tb_TopModule;
    reg clk;
    reg reset;
    reg [7:0] in;
    wire done;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .done(done)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 8'h00;
        #12;
        reset = 0;

        // Send a stream of bytes:
        // 0x00 (discard)
        // 0x08 (in[3]=1 -> Byte 1)
        // 0x00 (Byte 2)
        // 0x00 (Byte 3)
        // -> done should be high on the next cycle

        @(posedge clk);
        in = 8'h00; // ignored
        @(posedge clk);
        in = 8'h08; // Byte 1 (in[3]=1)
        @(posedge clk);
        in = 8'h12; // Byte 2
        @(posedge clk);
        in = 8'h34; // Byte 3
        @(posedge clk);
        // Here done should be 1
        if (done !== 1'b1) begin
            $display("FAIL: expected done=1 at cycle after byte 3");
            $finish;
        end
        in = 8'h00; // next byte without in[3]=1

        @(posedge clk);
        if (done !== 1'b0) begin
            $display("FAIL: expected done=0 after 1 cycle pulse");
            $finish;
        end

        // Test back-to-back packets where Byte 3 or subsequent byte has in[3]=1
        // Packet 2:
        // Byte 1: 8'h08 (in[3]=1)
        // Byte 2: 8'h00
        // Byte 3: 8'h08 (in[3]=1, should act as Byte 1 of next packet immediately in state S3!)
        @(posedge clk);
        in = 8'h08; // Byte 1
        @(posedge clk);
        in = 8'h00; // Byte 2
        @(posedge clk);
        in = 8'h08; // Byte 3 (has in[3]=1, starts next packet)
        @(posedge clk);
        // Here done should be 1 for packet 2, AND state should be S1 because in[3]=1 on byte 3.
        if (done !== 1'b1) begin
            $display("FAIL: expected done=1 for packet 2");
            $finish;
        end

        // Now we need 2 more bytes for packet 3 (since byte 3 of packet 2 was byte 1 of packet 3)
        @(posedge clk);
        if (done !== 1'b0) begin
            $display("FAIL: done should drop");
            $finish;
        end
        in = 8'hAA; // Byte 2 of packet 3
        @(posedge clk);
        in = 8'hBB; // Byte 3 of packet 3
        @(posedge clk);
        if (done !== 1'b1) begin
            $display("FAIL: expected done=1 for packet 3");
            $finish;
        end

        @(posedge clk);
        if (done !== 1'b0) begin
            $display("FAIL: done should drop");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

